def algorithm(func, dim, lb, ub, budget, rng):
    N = 50
    T = 1000
    p = 1.4
    c1 = 2.05
    c2 = 2.05
    w = 0.7
    alpha = 0.5

    x_best = np.random.uniform(lb, ub, size=dim)
    f_best = func(x_best)

    def generate_particles():
        particles = rng.normal(size=(N, dim))
        for i in range(N):
            particles[i] += lb + (ub - lb) * rng.uniform(size=dim)
        return particles

    def update_particles(particles, x_best):
        for i in range(N):
            r1 = rng.uniform(0, 1)
            r2 = rng.uniform(0, 1)
            p_i = w * particles[i] + c1 * r1 * (x_best - particles[i]) + c2 * r2 * (particles[np.argmax([func(particles[j]) for j in range(N)])] - particles[i])
            particles[i] = p_i
        return particles

    def update_temperature(T, f_best):
        if func(x_best) < f_best:
            T *= p
        return T

    particles = generate_particles()

    for _ in range(budget):
        particles = update_particles(particles, x_best)
        for i in range(N):
            f_i = func(particles[i])
            if f_i < f_best:
                f_best = f_i
                x_best = particles[i]
        T = update_temperature(T, f_best)

    return np.clip(x_best, lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def func_wrapper(x):
        x = clip(x)
        return func(x)

    pop_size = 10 * (dim + 1)
    mu = pop_size / 2
    sigma = 0.5 * (ub - lb)
    mean = rng.uniform(lb, ub, size=dim)
    covar = np.eye(dim) * sigma ** 2

    for _ in range(budget):
        offspring = np.random.multivariate_normal(mean, covar, pop_size)

        fitness = np.array([func_wrapper(x) for x in offspring])
        idx = np.argsort(fitness)[:mu]

        selected_offspring = offspring[idx]
        new_mean = np.mean(selected_offspring, axis=0)
        covar_new = 1 / (1 + 1 / mu) * np.eye(dim)

        for i in range(pop_size):
            if i < mu:
                covar_new += np.outer(offspring[i] - new_mean, offspring[i] - new_mean)
            else:
                covar_new += np.linalg.inv(mu * np.eye(dim)) @ (offspring[i] - new_mean)[:, None] @ (offspring[i] - new_mean)

        covar = 1 / (mu + 1) * covar + 1 / (mu * (mu + 1)) * covar_new

        mean = new_mean
        sigma = np.sqrt(np.diag(covar)).mean()

    best_solution = clip(mean)
    return best_solution

